class Solution:
    def countComponents(self, n: int, edges: List[List[int]]) -> int:
        graph = defaultdict(list)
        seen = set()
        ans = 0
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)

        def dfs(node: int) -> None:
            seen.add(node)
            for nei in graph[node]:
                if nei not in seen:
                    dfs(nei)

        for i in range(n):
            if i not in seen:
                dfs(i)
                ans += 1

        return ans
